insert into public.paintings (slug, title, description, medium, width_cm, height_cm, year, price_usd, status, featured, collection, style, colors, images, sort_order)
values
('two-shores', 'Two Shores', 'Two worlds side by side: a bright shore of turquoise, lime and sunshine yellow, and a dusky one of plum, slate and wine, scattered with tiny stars of paint. Between them runs a river of fine coloured lines where the two meet. Layered acrylic with dry-brush textures and splatters you can see up close.', 'Acrylic on canvas', 90, 60, 2025, 650, 'available', true, 'Abstract Rhythms', 'Abstract', '{blue,yellow,purple}', '[{"url":"/samples/two-shores.jpg","alt":"Two Shores, acrylic on canvas by Farah in Color"},{"url":"/samples/two-shores-detail.jpg","alt":"Close-up detail of the brushwork in Two Shores"}]'::jsonb, 0),
('coral-bloom', 'Coral Bloom', 'An explosion of petals in coral and blush, painted in loose, joyful strokes. A piece that brings warmth to any wall.', 'Acrylic on canvas', 60, 60, 2025, 520, 'available', true, 'Bloom', 'Floral', '{coral,pink,green}', '[{"url":"/samples/coral-bloom.jpg","alt":"Coral Bloom, acrylic on canvas by Farah in Color"},{"url":"/samples/coral-bloom-detail.jpg","alt":"Close-up detail of the brushwork in Coral Bloom"}]'::jsonb, 1),
('cedar-morning', 'Cedar Morning', 'Mist lifting over the cedars at dawn. Soft greens and blues meet warm earth tones in this large, calm landscape.', 'Oil on canvas', 120, 80, 2024, 1200, 'reserved', true, 'Mediterranean Light', 'Landscape', '{green,blue,earth}', '[{"url":"/samples/cedar-morning.jpg","alt":"Cedar Morning, oil on canvas by Farah in Color"},{"url":"/samples/cedar-morning-detail.jpg","alt":"Close-up detail of the brushwork in Cedar Morning"}]'::jsonb, 2),
('teal-whisper', 'Teal Whisper', 'A small, quiet piece of deep teal crossed with fine lines of gold leaf. Perfect for a desk, shelf or gallery wall.', 'Acrylic on canvas', 30, 40, 2025, 240, 'available', false, 'Abstract Rhythms', 'Abstract', '{teal,gold}', '[{"url":"/samples/teal-whisper.jpg","alt":"Teal Whisper, acrylic on canvas by Farah in Color"},{"url":"/samples/teal-whisper-detail.jpg","alt":"Close-up detail of the brushwork in Teal Whisper"}]'::jsonb, 3),
('jasmine-afternoon', 'Jasmine Afternoon', 'Jasmine climbing an old stone wall, painted from memories of summer afternoons in the mountains.', 'Acrylic on canvas', 50, 70, 2024, 430, 'sold', false, 'Bloom', 'Floral', '{white,green,yellow}', '[{"url":"/samples/jasmine-afternoon.jpg","alt":"Jasmine Afternoon, acrylic on canvas by Farah in Color"},{"url":"/samples/jasmine-afternoon-detail.jpg","alt":"Close-up detail of the brushwork in Jasmine Afternoon"}]'::jsonb, 4),
('rhythm-in-red', 'Rhythm in Red', 'Bold gestures of red and coral dance across a charcoal ground. Energetic and confident: a statement piece for a living room.', 'Mixed media on canvas', 90, 90, 2025, 950, 'available', true, 'Abstract Rhythms', 'Abstract', '{red,coral,black}', '[{"url":"/samples/rhythm-in-red.jpg","alt":"Rhythm in Red, mixed media on canvas by Farah in Color"},{"url":"/samples/rhythm-in-red-detail.jpg","alt":"Close-up detail of the brushwork in Rhythm in Red"}]'::jsonb, 5),
('byblos-blue', 'Byblos Blue', 'The old harbour of Byblos in a hundred shades of blue, with whitewashed light bouncing off the water.', 'Oil on canvas', 70, 50, 2023, 610, 'available', false, 'Mediterranean Light', 'Landscape', '{blue,white}', '[{"url":"/samples/byblos-blue.jpg","alt":"Byblos Blue, oil on canvas by Farah in Color"},{"url":"/samples/byblos-blue-detail.jpg","alt":"Close-up detail of the brushwork in Byblos Blue"}]'::jsonb, 6),
('golden-hour-figure', 'Golden Hour', 'A woman''s silhouette dissolving into the warm light of sunset. Simple shapes, warm feeling.', 'Acrylic on canvas', 40, 50, 2025, 380, 'available', false, 'Abstract Rhythms', 'Figurative', '{yellow,earth,coral}', '[{"url":"/samples/golden-hour-figure.jpg","alt":"Golden Hour, acrylic on canvas by Farah in Color"},{"url":"/samples/golden-hour-figure-detail.jpg","alt":"Close-up detail of the brushwork in Golden Hour"}]'::jsonb, 7),
('pomegranate-season', 'Pomegranate Season', 'Ripe pomegranates spilling their jewels across a linen cloth. A celebration of autumn colour.', 'Acrylic on canvas', 80, 60, 2024, 690, 'available', false, 'Bloom', 'Still life', '{red,pink,green}', '[{"url":"/samples/pomegranate-season.jpg","alt":"Pomegranate Season, acrylic on canvas by Farah in Color"},{"url":"/samples/pomegranate-season-detail.jpg","alt":"Close-up detail of the brushwork in Pomegranate Season"}]'::jsonb, 8),
('lavender-dusk', 'Lavender Dusk', 'Soft violet and rose blending into twilight blue. Dreamy, calm and meditative.', 'Acrylic on canvas', null, null, 2025, 450, 'available', false, 'Abstract Rhythms', 'Abstract', '{purple,pink,blue}', '[{"url":"/samples/lavender-dusk.jpg","alt":"Lavender Dusk, acrylic on canvas by Farah in Color"},{"url":"/samples/lavender-dusk-detail.jpg","alt":"Close-up detail of the brushwork in Lavender Dusk"}]'::jsonb, 9),
